# Problem: max profit from one buy + one sell, buy before sell.
# Track the minimum price seen so far; the answer is max(price - min_so_far).
# Linear pass; no need to compare every pair.
def max_profit(prices):
    if not prices:
        return 0
    best = 0
    lo = prices[0]
    for p in prices[1:]:
        if p < lo:
            lo = p
        elif p - lo > best:
            best = p - lo
    return best
```

